const diff=await cm('memo_diff',{sourceId:'clm-evidence',fromRevision:1,toRevision:2}); check(diff.ok && diff.changed && diff.from.sha256===p1.sha256 && diff.to.sha256===p2.sha256,'EXACT_DIFF');
const foreign=await cm('memo_get',{locator:'context://000000000000000000000000/clm-evidence@1/'+p1.sha256}); check(foreign.code==='INVALID_LOCATOR','TEAM_LOCATOR_DENIAL');
