const state=await cm('state',{}); check(state.ok && state.mode==='shadow' && state.viewRevision===0,'SHADOW_STATE');
const operations=[{op:'select',sourceId:'clm-evidence',revision:2,sha256:p2.sha256}];
const proposal=await cm('propose',{expectedRevision:0,operations}); check(proposal.ok,'PROPOSE');
const preview=await cm('preview',{proposalId:proposal.proposalId,expectedRevision:0}); check(preview.ok && preview.originalHistoryPreserved && preview.authorityPreserved,'PREVIEW_AUTHORITY');
const commit=await cm('commit',{proposalId:proposal.proposalId,expectedRevision:0}); check(commit.ok && commit.mode==='shadow' && commit.viewRevision===1 && commit.nextBoundaryOnly,'SHADOW_COMMIT');
return {stage:'shadow-bootstrap',oracle:oracle(quotes),taskId:task.id,memoSha256:p2.sha256,viewRevision:1};

